8: // WithSYNScan sets the scan technique to use SYN packets over TCP.
9: // This is the default method, as it is fast, stealthy and not
10: // hampered by restrictive firewalls.
11: func WithSYNScan() Option {
12: 	return func(s *Scanner) error {
13: 		s.args = append(s.args, "-sS")
14: 		return nil
15: 	}
16: }
17: 
18: // WithConnectScan sets the scan technique to use TCP connections.
19: // This is the default method used when a user does not have raw
20: // packet privileges. Target machines are likely to log these
21: // connections.
22: func WithConnectScan() Option {
23: 	return func(s *Scanner) error {
24: 		s.args = append(s.args, "-sT")
25: 		return nil
26: 	}
27: }
28: 
29: // WithACKScan sets the scan technique to use ACK packets over TCP.
30: // This scan is unable to determine if a port is open.
31: // When scanning unfiltered systems, open and closed ports both
32: // return an RST packet.
33: // Nmap then labels them as unfiltered, meaning that they are reachable
34: // by the ACK packet, but whether they are open or closed is undetermined.
35: func WithACKScan() Option {
36: 	return func(s *Scanner) error {
37: 		s.args = append(s.args, "-sA")
38: 		return nil
39: 	}
40: }
41: 
42: // WithWindowScan sets the scan technique to use ACK packets over TCP and
43: // examining the TCP window field of the RST packets returned.
44: // Window scan is exactly the same as ACK scan except that it exploits
45: // an implementation detail of certain systems to differentiate open ports
46: // from closed ones, rather than always printing unfiltered when a RST
47: // is returned.
48: func WithWindowScan() Option {
49: 	return func(s *Scanner) error {
50: 		s.args = append(s.args, "-sW")
51: 		return nil
52: 	}
53: }
54: 
55: // WithMaimonScan sends the same packets as NULL, FIN, and Xmas scans,
56: // except that the probe is FIN/ACK. Many BSD-derived systems drop
57: // these packets if the port is open.
58: func WithMaimonScan() Option {
59: 	return func(s *Scanner) error {
60: 		s.args = append(s.args, "-sM")
61: 		return nil
62: 	}
63: }
64: 
65: // WithUDPScan sets the scan technique to use UDP packets.
66: // It can be combined with a TCP scan type such as SYN scan
67: // to check both protocols during the same run.
68: // UDP scanning is generally slower than TCP, but should not
69: // be ignored.
70: //
71: // NOTE: UDP scans might require elevated privileges.
72: func WithUDPScan() Option {
73: 	return func(s *Scanner) error {
74: 		s.args = append(s.args, "-sU")
75: 		return nil
76: 	}
77: }
78: 
79: // WithTCPNullScan sets the scan technique to use TCP null packets.
80: // (TCP flag header is 0). This scan method can be used to exploit
81: // a loophole in the TCP RFC.
82: // If an RST packet is received, the port is considered closed,
83: // while no response means it is open|filtered.
84: func WithTCPNullScan() Option {
85: 	return func(s *Scanner) error {
86: 		s.args = append(s.args, "-sN")
87: 		return nil
88: 	}
89: }
90: 
91: // WithTCPFINScan sets the scan technique to use TCP packets with
